sql:
-- Initial schema · Dream Starter Kit
-- Single baseline migration (squashed from the original 0001–0008 series;
-- re-squashed once more when the feature slices moved into extensions — their
-- tables now ship as ext_<slug>_* migrations under extensions/*/supabase).
-- Sections: identity · teams · files+storage. CORE tables only — feature
-- tables (chat, reminders, notifications, billing) live in their extensions.
-- Every table has RLS with owner-scoped policies — see docs/ERD.md (source of truth).

create extension if not exists pgcrypto;

-- ============================================================================
-- Identity
-- profiles: app-level user record, 1:1 with auth.users (same id). The anchor
-- for most RLS policies. Created by a trigger on signup. (docs/ERD.md)
-- ============================================================================

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text,
  avatar_url text,
  created_at timestamptz not null default now(),
  is_staff boolean not null default false
);

comment on table public.profiles is
  'App-level user record, 1:1 with auth.users (same id). Created by handle_new_user() on signup.';

comment on column public.profiles.is_staff is
  'Grants access to the Payload CMS admin via the Supabase->Payload SSO bridge. The first signup is auto-flagged; default-deny otherwise.';

-- Mirror auth.users -> profiles on signup. SECURITY DEFINER so it can insert
-- regardless of RLS; empty search_path is the Supabase security best practice
-- (every reference is schema-qualified). The FIRST profile created is flagged
-- staff (the founder/admin) — default-deny for everyone after.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name, avatar_url, is_staff)
  values (
    new.id,
    coalesce(
      new.raw_user_meta_data ->> 'display_name',
      new.raw_user_meta_data ->> 'name',
      split_part(coalesce(new.email, ''), '@', 1)
    ),
    new.raw_user_meta_data ->> 'avatar_url',
    -- First profile in the table becomes staff (the founder/admin).
    (select count(*) = 0 from public.profiles)
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- RLS: a user sees/updates only their own profile. Inserts happen via the
-- trigger (SECURITY DEFINER); deletes cascade from auth.users.
alter table public.profiles enable row level security;

create policy "profiles: select own"
  on public.profiles for select to authenticated
  using (id = (select auth.uid()));

create policy "profiles: update own"
  on public.profiles for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

-- Prevent privilege escalation: the "profiles: update own" RLS policy would otherwise
-- let a user flip their own is_staff. A column-level revoke can't subtract from a
-- table-level grant, so revoke table UPDATE and re-grant only the user-editable columns.
-- (RLS still scopes updates to the user's own row; SECURITY DEFINER functions and the
-- service_role keep full access and set is_staff out-of-band.)
revoke update on public.profiles from authenticated, anon;
grant update (display_name, avatar_url) on public.profiles to authenticated;

-- ============================================================================
-- Teams / multi-tenancy (optional — drop for single-user apps)
-- organizations, memberships, invitations. Org-scoped RLS uses SECURITY DEFINER
-- helpers to avoid infinite recursion on the memberships table. (docs/ERD.md)
-- ============================================================================

create table public.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  owner_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now()
);
create index on public.organizations (owner_id);

create table public.memberships (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  role text not null default 'member' check (role in ('owner', 'admin', 'member')),
  created_at timestamptz not null default now(),
  unique (org_id, user_id)
);
-- Indexes on FKs used in RLS predicates.
create index on public.memberships (org_id);
create index on public.memberships (user_id);

create table public.invitations (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations (id) on delete cascade,
  email text not null,
  role text not null default 'member' check (role in ('owner', 'admin', 'member')),
  status text not null default 'pending' check (status in ('pending', 'accepted')),
  created_at timestamptz not null default now()
);
create index on public.invitations (org_id);

-- Membership helpers. SECURITY DEFINER runs as the function owner, so the
-- internal SELECT on memberships does NOT re-trigger memberships' RLS (which
-- would recurse). This is the canonical Supabase pattern.
create or replace function public.is_org_member(_org uuid)
returns boolean language sql security definer set search_path = '' stable as $$
  select exists (
    select 1 from public.memberships m
    where m.org_id = _org and m.user_id = (select auth.uid())
  );
$$;

create or replace function public.is_org_admin(_org uuid)
returns boolean language sql security definer set search_path = '' stable as $$
  select exists (
    select 1 from public.memberships m
    where m.org_id = _org
      and m.user_id = (select auth.uid())
      and m.role in ('owner', 'admin')
  );
$$;

-- On org creation, enroll the owner as an 'owner' member (avoids the
-- chicken-and-egg where the admin-only insert policy would block the first row).
create or replace function public.handle_new_organization()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.memberships (org_id, user_id, role)
  values (new.id, new.owner_id, 'owner')
  on conflict (org_id, user_id) do nothing;
  return new;
end;
$$;

create trigger on_organization_created
  after insert on public.organizations
  for each row execute function public.handle_new_organization();

alter table public.organizations enable row level security;
alter table public.memberships enable row level security;
alter table public.invitations enable row level security;

-- organizations: members read; owner creates/updates/deletes.
create policy "orgs: select if member"
  on public.organizations for select to authenticated
  using (owner_id = (select auth.uid()) or public.is_org_member(id));
create policy "orgs: insert own"
  on public.organizations for insert to authenticated
  with check (owner_id = (select auth.uid()));
create policy "orgs: update owner"
  on public.organizations for update to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));
create policy "orgs: delete owner"
  on public.organizations for delete to authenticated
  using (owner_id = (select auth.uid()));

-- memberships: members read co-members; admins manage. The first (owner) row
-- is created by the trigger above (SECURITY DEFINER).
create policy "memberships: select if member"
  on public.memberships for select to authenticated
  using (public.is_org_member(org_id));
create policy "memberships: admins insert"
  on public.memberships for insert to authenticated
  with check (public.is_org_admin(org_id));
create policy "memberships: admins update"
  on public.memberships for update to authenticated
  using (public.is_org_admin(org_id))
  with check (public.is_org_admin(org_id));
create policy "memberships: admins delete"
  on public.memberships for delete to authenticated
  using (public.is_org_admin(org_id));

-- invitations: org admins manage.
create policy "invitations: admins all"
  on public.invitations for all to authenticated
  using (public.is_org_admin(org_id))
  with check (public.is_org_admin(org_id));

-- ============================================================================
-- Files + Storage
-- `files` is metadata for objects in Supabase Storage. The bucket's RLS lives on
-- storage.objects, path-prefixed by user id (convention: "<user_id>/..."),
-- mirroring the files table's ownership. (docs/ERD.md)
-- ============================================================================

create table public.files (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  bucket text not null default 'user-files',
  path text not null, -- Storage object path, e.g. "<user_id>/avatar.png"
  mime_type text,
  size_bytes bigint,
  created_at timestamptz not null default now(),
  unique (bucket, path)
);
create index on public.files (user_id);

alter table public.files enable row level security;

create policy "files: own"
  on public.files for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Private bucket for user uploads.
insert into storage.buckets (id, name, public)
values ('user-files', 'user-files', false)
on conflict (id) do nothing;

-- Storage RLS: a user may only touch objects under their own "<user_id>/" prefix.
create policy "user-files: select own"
  on storage.objects for select to authenticated
  using (bucket_id = 'user-files' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "user-files: insert own"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'user-files' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "user-files: update own"
  on storage.objects for update to authenticated
  using (bucket_id = 'user-files' and (storage.foldername(name))[1] = (select auth.uid())::text)
  with check (bucket_id = 'user-files' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "user-files: delete own"
  on storage.objects for delete to authenticated
  using (bucket_id = 'user-files' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- Billing extension · initial schema (Stripe-synced mirror)
-- Clients may READ their own customer/subscription rows; the product catalog is
-- world-readable. NO write policies exist for clients — the Stripe webhook
-- (billing-stripe-webhook edge function) writes these using the service role,
-- which bypasses RLS entirely. DDL is reattach-friendly (if not exists /
-- drop-then-create policies) so a reinstall after `ext remove --keep-data`
-- adopts the surviving tables.

create table if not exists public.ext_billing_customers (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null unique references public.profiles (id) on delete cascade,
  stripe_customer_id text not null unique,
  created_at timestamptz not null default now()
);
create index if not exists ext_billing_customers_user_id_idx
  on public.ext_billing_customers (user_id);

create table if not exists public.ext_billing_products (
  id text primary key, -- Stripe product id
  active boolean not null default true,
  name text,
  description text,
  image text,
  metadata jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.ext_billing_prices (
  id text primary key, -- Stripe price id
  product_id text references public.ext_billing_products (id) on delete cascade,
  active boolean not null default true,
  unit_amount integer,
  currency text,
  type text check (type in ('one_time', 'recurring')),
  interval text check (interval in ('day', 'week', 'month', 'year')),
  interval_count integer,
  metadata jsonb,
  created_at timestamptz not null default now()
);
create index if not exists ext_billing_prices_product_id_idx
  on public.ext_billing_prices (product_id);

create table if not exists public.ext_billing_subscriptions (
  id text primary key, -- Stripe subscription id
  user_id uuid not null references public.profiles (id) on delete cascade,
  price_id text references public.ext_billing_prices (id),
  status text check (
    status in (
      'trialing', 'active', 'past_due', 'canceled',
      'incomplete', 'incomplete_expired', 'unpaid', 'paused'
    )
  ),
  quantity integer,
  cancel_at_period_end boolean not null default false,
  current_period_end timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists ext_billing_subscriptions_user_id_idx
  on public.ext_billing_subscriptions (user_id);
create index if not exists ext_billing_subscriptions_price_id_idx
  on public.ext_billing_subscriptions (price_id);

alter table public.ext_billing_customers enable row level security;
alter table public.ext_billing_products enable row level security;
alter table public.ext_billing_prices enable row level security;
alter table public.ext_billing_subscriptions enable row level security;

-- Read own only (no write policies => clients cannot write; webhook uses service role).
drop policy if exists "ext_billing_customers: select own" on public.ext_billing_customers;
create policy "ext_billing_customers: select own"
  on public.ext_billing_customers for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists "ext_billing_subscriptions: select own" on public.ext_billing_subscriptions;
create policy "ext_billing_subscriptions: select own"
  on public.ext_billing_subscriptions for select to authenticated
  using (user_id = (select auth.uid()));

-- Public catalog: anyone may read products/prices (e.g. a pricing page).
drop policy if exists "ext_billing_products: read all" on public.ext_billing_products;
create policy "ext_billing_products: read all"
  on public.ext_billing_products for select to authenticated, anon
  using (true);

drop policy if exists "ext_billing_prices: read all" on public.ext_billing_prices;
create policy "ext_billing_prices: read all"
  on public.ext_billing_prices for select to authenticated, anon
  using (true);

-- AI Chat extension · initial schema
-- ext_chat_threads / ext_chat_messages back the in-app assistant (AI SDK via
-- the AI Gateway). token_usage supports cost/observability. DDL is
-- reattach-friendly (if not exists / drop-then-create policies) so a reinstall
-- after `ext remove --keep-data` adopts the surviving tables.

create table if not exists public.ext_chat_threads (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  title text,
  created_at timestamptz not null default now()
);
create index if not exists ext_chat_threads_user_id_idx
  on public.ext_chat_threads (user_id);

create table if not exists public.ext_chat_messages (
  id uuid primary key default gen_random_uuid(),
  thread_id uuid not null references public.ext_chat_threads (id) on delete cascade,
  role text not null check (role in ('user', 'assistant', 'system')),
  content text not null default '',
  token_usage jsonb,
  created_at timestamptz not null default now()
);
create index if not exists ext_chat_messages_thread_id_idx
  on public.ext_chat_messages (thread_id);

alter table public.ext_chat_threads enable row level security;
alter table public.ext_chat_messages enable row level security;

drop policy if exists "ext_chat_threads: own" on public.ext_chat_threads;
create policy "ext_chat_threads: own"
  on public.ext_chat_threads for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Messages are reachable only through a thread the user owns.
drop policy if exists "ext_chat_messages: via own thread" on public.ext_chat_messages;
create policy "ext_chat_messages: via own thread"
  on public.ext_chat_messages for all to authenticated
  using (
    exists (
      select 1 from public.ext_chat_threads t
      where t.id = ext_chat_messages.thread_id and t.user_id = (select auth.uid())
    )
  )
  with check (
    exists (
      select 1 from public.ext_chat_threads t
      where t.id = ext_chat_messages.thread_id and t.user_id = (select auth.uid())
    )
  );

-- Notifications extension · initial schema
-- ext_notifications (in-app feed) + ext_notifications_push_tokens (Expo device
-- registrations). Strictly user-owned under RLS; servers write via the service
-- role. DDL is reattach-friendly (if not exists / drop-then-create policies)
-- so a reinstall after `ext remove --keep-data` adopts the surviving tables.

create table if not exists public.ext_notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  type text not null,
  title text,
  body text,
  data jsonb not null default '{}'::jsonb,
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists ext_notifications_user_id_idx
  on public.ext_notifications (user_id);

create table if not exists public.ext_notifications_push_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  token text not null, -- Expo push token
  platform text not null check (platform in ('ios', 'android', 'web')),
  created_at timestamptz not null default now(),
  unique (user_id, token)
);
create index if not exists ext_notifications_push_tokens_user_id_idx
  on public.ext_notifications_push_tokens (user_id);

alter table public.ext_notifications enable row level security;
alter table public.ext_notifications_push_tokens enable row level security;

-- notifications are typically written by the server (service role), but a user
-- may read/mark-read/delete their own.
drop policy if exists "ext_notifications: own" on public.ext_notifications;
create policy "ext_notifications: own"
  on public.ext_notifications for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

drop policy if exists "ext_notifications_push_tokens: own"
  on public.ext_notifications_push_tokens;
create policy "ext_notifications_push_tokens: own"
  on public.ext_notifications_push_tokens for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Reminders extension · initial schema
-- ext_reminders: user-owned scheduled nudges. DDL is reattach-friendly
-- (if not exists / drop-then-create policies) so a reinstall after
-- `ext remove --keep-data` adopts the surviving table.

create table if not exists public.ext_reminders (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  due_at timestamptz not null,
  channel text not null default 'push' check (channel in ('push', 'email')),
  status text not null default 'pending' check (status in ('pending', 'sent', 'canceled')),
  created_at timestamptz not null default now()
);
create index if not exists ext_reminders_user_id_idx
  on public.ext_reminders (user_id);
-- The scheduler (reminders-process edge function) scans due+pending.
create index if not exists ext_reminders_status_due_at_idx
  on public.ext_reminders (status, due_at);

alter table public.ext_reminders enable row level security;

drop policy if exists "ext_reminders: own" on public.ext_reminders;
create policy "ext_reminders: own"
  on public.ext_reminders for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Demo extension · initial schema (owner-scoped, canonical RLS pattern).
create table if not exists public.ext_demo_items (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  title text not null,
  created_at timestamptz not null default now()
);
create index if not exists ext_demo_items_user_id_idx on public.ext_demo_items (user_id);

alter table public.ext_demo_items enable row level security;

drop policy if exists "ext_demo_items: own" on public.ext_demo_items;
create policy "ext_demo_items: own"
  on public.ext_demo_items for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Teardown for the removed "demo" extension (pnpm ext remove).
-- Teardown for `pnpm ext remove demo` (skipped with --keep-data).
drop table if exists public.ext_demo_items cascade;

-- ============================================================================
-- chat-uploads bucket — per-user chat attachments (images sent to the AI).
--
-- Owned by the HOST, not the chat extension: extension SQL may not touch the
-- storage schema (lintExtensionSql), so the bucket + object policies live
-- here — the same split as cms-media / extension-uploads. Private bucket;
-- objects are written under <user_id>/<filename> and read back via
-- short-lived signed URLs minted by the chat extension's upload route.
-- ============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'chat-uploads',
  'chat-uploads',
  false,
  5242880, -- 5 MiB (matches the upload route's cap)
  array['image/png', 'image/jpeg']
)
on conflict (id) do nothing;

-- Owner-folder policies: an authenticated user may write/read only objects
-- whose first path segment is their own user id.
drop policy if exists "chat-uploads: insert own folder" on storage.objects;
create policy "chat-uploads: insert own folder"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'chat-uploads'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

drop policy if exists "chat-uploads: read own folder" on storage.objects;
create policy "chat-uploads: read own folder"
  on storage.objects for select to authenticated
  using (
    bucket_id = 'chat-uploads'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

drop policy if exists "chat-uploads: delete own folder" on storage.objects;
create policy "chat-uploads: delete own folder"
  on storage.objects for delete to authenticated
  using (
    bucket_id = 'chat-uploads'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

-- AI Chat extension · Chat SDK parity (vendored vercel/ai-chatbot UI)
-- Threads gain visibility/last_context/updated_at; messages gain structured
-- `parts` + `attachments` (UIMessage shape) while `content` stays as a
-- plain-text projection for the native screens. New artifact tables mirror
-- upstream Document/Suggestion/Vote, versioned by (id, created_at). DDL is
-- reattach-friendly (if not exists / drop-then-create policies).
-- The chat-uploads storage bucket lives in a HOST migration (extensions may
-- not touch the storage schema).

alter table public.ext_chat_threads
  add column if not exists visibility text not null default 'private'
    check (visibility in ('private', 'public')),
  add column if not exists last_context jsonb,
  add column if not exists updated_at timestamptz not null default now();

alter table public.ext_chat_messages
  add column if not exists parts jsonb,
  add column if not exists attachments jsonb not null default '[]'::jsonb;

-- Artifact documents: append-only versions keyed by (id, created_at) — the
-- upstream Chat SDK versioning model (every save inserts a new version row).
create table if not exists public.ext_chat_documents (
  id uuid not null default gen_random_uuid(),
  created_at timestamptz not null default now(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  title text not null,
  content text,
  kind text not null default 'text'
    check (kind in ('text', 'code', 'image', 'sheet')),
  primary key (id, created_at)
);
create index if not exists ext_chat_documents_user_id_idx
  on public.ext_chat_documents (user_id);

create table if not exists public.ext_chat_suggestions (
  id uuid primary key default gen_random_uuid(),
  document_id uuid not null,
  document_created_at timestamptz not null,
  original_text text not null,
  suggested_text text not null,
  description text,
  is_resolved boolean not null default false,
  user_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  foreign key (document_id, document_created_at)
    references public.ext_chat_documents (id, created_at) on delete cascade
);
create index if not exists ext_chat_suggestions_document_idx
  on public.ext_chat_suggestions (document_id, document_created_at);

create table if not exists public.ext_chat_votes (
  thread_id uuid not null references public.ext_chat_threads (id) on delete cascade,
  message_id uuid not null references public.ext_chat_messages (id) on delete cascade,
  is_upvoted boolean not null,
  primary key (thread_id, message_id)
);

alter table public.ext_chat_documents enable row level security;
alter table public.ext_chat_suggestions enable row level security;
alter table public.ext_chat_votes enable row level security;

drop policy if exists "ext_chat_documents: own" on public.ext_chat_documents;
create policy "ext_chat_documents: own"
  on public.ext_chat_documents for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

drop policy if exists "ext_chat_suggestions: own" on public.ext_chat_suggestions;
create policy "ext_chat_suggestions: own"
  on public.ext_chat_suggestions for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Votes are reachable only through a thread the user owns.
drop policy if exists "ext_chat_votes: via own thread" on public.ext_chat_votes;
create policy "ext_chat_votes: via own thread"
  on public.ext_chat_votes for all to authenticated
  using (
    exists (
      select 1 from public.ext_chat_threads t
      where t.id = ext_chat_votes.thread_id and t.user_id = (select auth.uid())
    )
  )
  with check (
    exists (
      select 1 from public.ext_chat_threads t
      where t.id = ext_chat_votes.thread_id and t.user_id = (select auth.uid())
    )
  );

-- Modules used to be called "extensions", and their tables used the
-- `ext_` prefix. Rename this module's tables to `mod_*`, then rename the
-- constraints, indexes and RLS policies on them that still carry the old
-- prefix. Renames keep data, grants, RLS and foreign keys intact. Idempotent:
-- a no-op where the rename already happened.
alter table if exists public.ext_chat_threads rename to mod_chat_threads;
alter table if exists public.ext_chat_messages rename to mod_chat_messages;
alter table if exists public.ext_chat_documents rename to mod_chat_documents;
alter table if exists public.ext_chat_suggestions rename to mod_chat_suggestions;
alter table if exists public.ext_chat_votes rename to mod_chat_votes;
alter table if exists public.ext_chat_channel_contacts rename to mod_chat_channel_contacts;
alter table if exists public.ext_chat_channel_threads rename to mod_chat_channel_threads;
alter table if exists public.ext_chat_processed_inbound rename to mod_chat_processed_inbound;
alter table if exists public.ext_chat_outbound_counters rename to mod_chat_outbound_counters;

do $$
declare
  own text[] := array['mod_chat_threads', 'mod_chat_messages', 'mod_chat_documents', 'mod_chat_suggestions', 'mod_chat_votes', 'mod_chat_channel_contacts', 'mod_chat_channel_threads', 'mod_chat_processed_inbound', 'mod_chat_outbound_counters'];
  r record;
begin
  for r in
    select t.relname as tbl, c.conname as name
    from pg_constraint c
    join pg_class t on t.oid = c.conrelid
    join pg_namespace n on n.oid = t.relnamespace
    where n.nspname = 'public' and t.relname = any (own) and c.conname like 'ext\_%'
  loop
    execute format('alter table %I.%I rename constraint %I to %I',
      'public', r.tbl, r.name, 'mod_' || substr(r.name, 5));
  end loop;

  for r in
    select i.relname as name
    from pg_index x
    join pg_class i on i.oid = x.indexrelid
    join pg_class t on t.oid = x.indrelid
    join pg_namespace n on n.oid = t.relnamespace
    where n.nspname = 'public' and t.relname = any (own) and i.relname like 'ext\_%'
  loop
    execute format('alter index %I.%I rename to %I',
      'public', r.name, 'mod_' || substr(r.name, 5));
  end loop;

  for r in
    select t.relname as tbl, p.polname as name
    from pg_policy p
    join pg_class t on t.oid = p.polrelid
    join pg_namespace n on n.oid = t.relnamespace
    where n.nspname = 'public' and t.relname = any (own) and p.polname like 'ext\_%'
  loop
    execute format('alter policy %I on %I.%I rename to %I',
      r.name, 'public', r.tbl, 'mod_' || substr(r.name, 5));
  end loop;
end
$$;

-- Workspaces (B2B) core · docs/WORKSPACES.md, docs/ERD.md
--
-- Turns the baseline organizations / memberships / invitations tables into
-- usable workspaces: URL slugs, an invite-link token, onboarding progress,
-- secure email-invite tokens, and the SECURITY DEFINER RPCs every
-- cross-boundary write goes through. Also adds the profile fields the
-- onboarding steps write (title, active workspace, email preferences), a
-- co-member profile read policy, and RESTRICTIVE no-anon policies.
--
-- The founder-level `accountModel` setting (consumer | business | hybrid)
-- lives in the Payload authentication-settings global and NEVER touches RLS:
-- everything here is inert until the app starts calling it.
--
-- Append-only + idempotent-friendly (if not exists / drop-then-create).

-- ============================================================================
-- Slug rules — the SAME list + pattern live in packages/app/src/workspaces.ts
-- (client-side validation). Keep them in sync.
-- ============================================================================

create or replace function public.is_reserved_slug(_slug text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select lower(_slug) = any (array[
    'a', 'admin', 'api', 'auth', 'billing', 'cms-api', 'cms-setup', 'invite',
    'join', 'mcp', 'oauth', 'onboarding', 'pricing', 'profile', 'sign-in',
    'sign-up', 'welcome', 'w', 'www'
  ]);
$$;

comment on function public.is_reserved_slug(text) is
  'True for workspace slugs that collide with app routes. Mirrored in packages/app/src/workspaces.ts.';

-- ============================================================================
-- organizations: slug, branding, invite link, domain-restricted joins
-- ============================================================================

-- Lowercase-only by pattern, so plain text + unique is case-insensitive in
-- practice (no citext dependency). Existing rows (and direct inserts that omit
-- it) get a random, valid, non-reserved `org-xxxxxxxxxxxx` default; the
-- create_workspace RPC always sets a chosen slug.
alter table public.organizations
  add column if not exists slug text not null
    default ('org-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));
alter table public.organizations add column if not exists logo_url text;
alter table public.organizations add column if not exists join_token_hash text;
alter table public.organizations
  add column if not exists join_link_enabled boolean not null default true;
alter table public.organizations
  add column if not exists allowed_domains text[] not null default '{}';
alter table public.organizations
  add column if not exists data jsonb not null default '{}'::jsonb;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'organizations_slug_key'
  ) then
    alter table public.organizations
      add constraint organizations_slug_key unique (slug);
  end if;
  if not exists (
    select 1 from pg_constraint where conname = 'organizations_slug_format'
  ) then
    alter table public.organizations
      add constraint organizations_slug_format
        check (slug ~ '^[a-z0-9](-?[a-z0-9]){1,38}$');
  end if;
  if not exists (
    select 1 from pg_constraint where conname = 'organizations_slug_not_reserved'
  ) then
    alter table public.organizations
      add constraint organizations_slug_not_reserved
        check (not public.is_reserved_slug(slug));
  end if;
  if not exists (
    select 1 from pg_constraint where conname = 'organizations_join_token_hash_key'
  ) then
    alter table public.organizations
      add constraint organizations_join_token_hash_key unique (join_token_hash);
  end if;
end;
$$;

comment on column public.organizations.slug is
  'Workspace URL slug (lowercase, 2–39 chars, no leading/trailing/double hyphen, not reserved).';
comment on column public.organizations.join_token_hash is
  'SHA-256 (hex) of the rotating invite-link token. The plaintext is shown once and never stored.';
comment on column public.organizations.allowed_domains is
  'When non-empty, invite-link joins require an email at one of these domains.';

-- ============================================================================
-- memberships: per-person onboarding progress (resume the stepper)
-- ============================================================================

alter table public.memberships add column if not exists onboarding_step text;
alter table public.memberships
  add column if not exists onboarding_completed_at timestamptz;
alter table public.memberships
  add column if not exists onboarding_done text[] not null default '{}';

comment on column public.memberships.onboarding_step is
  'Key of the next onboarding step to show this member in this workspace (null = not started).';
comment on column public.memberships.onboarding_done is
  'Onboarding step keys this member finished (vs skipped) — drives the getting-started checklist.';

-- ============================================================================
-- invitations: hashed token, expiry, audit, revoke
-- ============================================================================

alter table public.invitations add column if not exists token_hash text;
alter table public.invitations
  add column if not exists invited_by uuid references public.profiles (id) on delete set null;
alter table public.invitations add column if not exists expires_at timestamptz;
alter table public.invitations add column if not exists accepted_at timestamptz;
alter table public.invitations
  add column if not exists accepted_by uuid references public.profiles (id) on delete set null;

alter table public.invitations drop constraint if exists invitations_status_check;
alter table public.invitations
  add constraint invitations_status_check
    check (status in ('pending', 'accepted', 'revoked'));

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'invitations_token_hash_key'
  ) then
    alter table public.invitations
      add constraint invitations_token_hash_key unique (token_hash);
  end if;
end;
$$;

-- One live invite per (workspace, email).
create unique index if not exists invitations_one_pending_per_email
  on public.invitations (org_id, lower(email))
  where status = 'pending';
create index if not exists invitations_email_lower_idx
  on public.invitations (lower(email));

comment on column public.invitations.token_hash is
  'SHA-256 (hex) of the 32-byte random invite token. The plaintext only ever lives in the emailed link.';

-- ============================================================================
-- profiles: title, active workspace, email preferences
-- ============================================================================

alter table public.profiles add column if not exists title text;
alter table public.profiles
  add column if not exists last_org_id uuid references public.organizations (id) on delete set null;
alter table public.profiles
  add column if not exists email_preferences jsonb not null default '{}'::jsonb;

comment on column public.profiles.last_org_id is
  'The workspace the user last had active. Must be a workspace they belong to (enforced by trigger).';
comment on column public.profiles.email_preferences is
  'Onboarding "Stay in the loop" choices, e.g. {"tips": true, "product_updates": false}.';

-- Same column-level grant pattern as display_name/avatar_url/phone.
grant update (title, last_org_id, email_preferences) on public.profiles to authenticated;

-- last_org_id is a preference, but never let it point at a workspace the user
-- doesn't belong to (prevents probing org ids via the FK and keeps
-- getActiveOrg() honest).
create or replace function public.guard_profile_last_org()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.last_org_id is not null
     and new.last_org_id is distinct from old.last_org_id
     and not exists (
       select 1 from public.memberships m
       where m.org_id = new.last_org_id and m.user_id = new.id
     ) then
    raise exception 'not_a_member' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_guard_last_org on public.profiles;
create trigger profiles_guard_last_org
  before update of last_org_id on public.profiles
  for each row execute function public.guard_profile_last_org();

-- ============================================================================
-- memberships: a workspace always keeps at least one owner
-- ============================================================================

-- Blocks demoting/removing the last owner. Cascades are exempt: when the
-- workspace itself or the member's profile is being deleted, the parent row is
-- already gone by the time the cascaded membership delete runs.
create or replace function public.guard_last_owner()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if old.role <> 'owner' then
    return coalesce(new, old);
  end if;
  if tg_op = 'UPDATE' and new.role = 'owner' and new.org_id = old.org_id then
    return new;
  end if;
  if not exists (select 1 from public.organizations o where o.id = old.org_id)
     or not exists (select 1 from public.profiles p where p.id = old.user_id) then
    return coalesce(new, old);
  end if;
  if not exists (
    select 1 from public.memberships m
    where m.org_id = old.org_id and m.role = 'owner' and m.id <> old.id
  ) then
    raise exception 'last_owner' using errcode = 'P0001',
      hint = 'Transfer ownership to another member first.';
  end if;
  return coalesce(new, old);
end;
$$;

drop trigger if exists memberships_guard_last_owner on public.memberships;
create trigger memberships_guard_last_owner
  before update or delete on public.memberships
  for each row execute function public.guard_last_owner();

-- ============================================================================
-- Helpers
-- ============================================================================

-- True when the caller's JWT is an anonymous (Turnstile) session.
create or replace function public.is_anonymous_session()
returns boolean
language sql
stable
set search_path = ''
as $$
  select coalesce(((select auth.jwt()) ->> 'is_anonymous')::boolean, false);
$$;

-- The caller's email, only when it is confirmed (security definer: reads auth.users).
create or replace function public.confirmed_email()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select lower(u.email)
  from auth.users u
  where u.id = (select auth.uid())
    and u.email is not null
    and u.email_confirmed_at is not null;
$$;

revoke execute on function public.confirmed_email() from public, anon;
grant execute on function public.confirmed_email() to authenticated;

-- ============================================================================
-- RPCs (security definer, empty search_path, authenticated only)
-- Errors are raised as stable snake_case messages the client maps to copy.
-- ============================================================================

-- is_slug_available: format + reserved + uniqueness.
create or replace function public.is_slug_available(_slug text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select
    _slug is not null
    and _slug ~ '^[a-z0-9](-?[a-z0-9]){1,38}$'
    and not public.is_reserved_slug(_slug)
    and not exists (select 1 from public.organizations o where o.slug = _slug);
$$;

-- create_workspace: non-anon caller creates a workspace and becomes its owner
-- (the on_organization_created trigger inserts the owner membership).
create or replace function public.create_workspace(_name text, _slug text)
returns public.organizations
language plpgsql
security definer
set search_path = ''
as $$
declare
  _uid uuid := (select auth.uid());
  _clean_name text := btrim(coalesce(_name, ''));
  _clean_slug text := lower(btrim(coalesce(_slug, '')));
  _org public.organizations;
begin
  if _uid is null or public.is_anonymous_session() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if char_length(_clean_name) < 1 or char_length(_clean_name) > 64 then
    raise exception 'invalid_name' using errcode = 'P0001';
  end if;
  if _clean_slug !~ '^[a-z0-9](-?[a-z0-9]){1,38}$' then
    raise exception 'invalid_slug' using errcode = 'P0001';
  end if;
  if public.is_reserved_slug(_clean_slug)
     or exists (select 1 from public.organizations o where o.slug = _clean_slug) then
    raise exception 'slug_unavailable' using errcode = 'P0001';
  end if;

  begin
    insert into public.organizations (name, slug, owner_id)
    values (_clean_name, _clean_slug, _uid)
    returning * into _org;
  exception when unique_violation then
    raise exception 'slug_unavailable' using errcode = 'P0001';
  end;

  update public.profiles set last_org_id = _org.id where id = _uid;
  return _org;
end;
$$;

-- accept_invitation: the invitee (confirmed email matching the invite) joins.
create or replace function public.accept_invitation(_token text)
returns public.organizations
language plpgsql
security definer
set search_path = ''
as $$
declare
  _uid uuid := (select auth.uid());
  _email text;
  _inv public.invitations;
  _org public.organizations;
begin
  if _uid is null or public.is_anonymous_session() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if _token is null or char_length(_token) < 16 then
    raise exception 'invite_not_found' using errcode = 'P0001';
  end if;

  select * into _inv from public.invitations i
  where i.token_hash = encode(sha256(convert_to(_token, 'UTF8')), 'hex')
  for update;
  if not found then
    raise exception 'invite_not_found' using errcode = 'P0001';
  end if;
  if _inv.status = 'revoked' then
    raise exception 'invite_revoked' using errcode = 'P0001';
  end if;
  if _inv.status = 'accepted' then
    -- Idempotent for the person who already accepted it.
    if _inv.accepted_by = _uid then
      select * into _org from public.organizations o where o.id = _inv.org_id;
      return _org;
    end if;
    raise exception 'invite_used' using errcode = 'P0001';
  end if;
  if _inv.expires_at is not null and _inv.expires_at <= now() then
    raise exception 'invite_expired' using errcode = 'P0001';
  end if;

  _email := public.confirmed_email();
  if _email is null or _email <> lower(_inv.email) then
    raise exception 'invite_wrong_account' using errcode = 'P0001';
  end if;

  insert into public.memberships (org_id, user_id, role)
  values (_inv.org_id, _uid, _inv.role)
  on conflict (org_id, user_id) do nothing;

  update public.invitations
  set status = 'accepted', accepted_at = now(), accepted_by = _uid
  where id = _inv.id;

  update public.profiles set last_org_id = _inv.org_id where id = _uid;

  select * into _org from public.organizations o where o.id = _inv.org_id;
  return _org;
end;
$$;

-- join_workspace_by_link: anyone with the (enabled) link joins as a member,
-- subject to the workspace's allowed email domains.
create or replace function public.join_workspace_by_link(_token text)
returns public.organizations
language plpgsql
security definer
set search_path = ''
as $$
declare
  _uid uuid := (select auth.uid());
  _email text;
  _org public.organizations;
begin
  if _uid is null or public.is_anonymous_session() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if _token is null or char_length(_token) < 16 then
    raise exception 'join_link_invalid' using errcode = 'P0001';
  end if;

  select * into _org from public.organizations o
  where o.join_token_hash = encode(sha256(convert_to(_token, 'UTF8')), 'hex');
  if not found then
    raise exception 'join_link_invalid' using errcode = 'P0001';
  end if;
  if not _org.join_link_enabled then
    raise exception 'join_link_disabled' using errcode = 'P0001';
  end if;

  _email := public.confirmed_email();
  if _email is null then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if cardinality(_org.allowed_domains) > 0
     and not (split_part(_email, '@', 2) = any (
       select lower(d) from unnest(_org.allowed_domains) as d
     )) then
    raise exception 'join_domain_not_allowed' using errcode = 'P0001';
  end if;

  insert into public.memberships (org_id, user_id, role)
  values (_org.id, _uid, 'member')
  on conflict (org_id, user_id) do nothing;

  update public.profiles set last_org_id = _org.id where id = _uid;
  return _org;
end;
$$;

-- my_pending_invitations: the invitee's only window onto their invites.
-- Never returns tokens. Matches the caller's CONFIRMED email only.
create or replace function public.my_pending_invitations()
returns table (
  invitation_id uuid,
  org_id uuid,
  org_name text,
  org_slug text,
  logo_url text,
  inviter_name text,
  role text,
  expires_at timestamptz
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    i.id,
    o.id,
    o.name,
    o.slug,
    o.logo_url,
    p.display_name,
    i.role,
    i.expires_at
  from public.invitations i
  join public.organizations o on o.id = i.org_id
  left join public.profiles p on p.id = i.invited_by
  where i.status = 'pending'
    and (i.expires_at is null or i.expires_at > now())
    and not public.is_anonymous_session()
    and lower(i.email) = public.confirmed_email()
    and not exists (
      select 1 from public.memberships m
      where m.org_id = i.org_id and m.user_id = (select auth.uid())
    )
  order by i.created_at desc;
$$;

-- save_onboarding_progress: a member records their own stepper position in a
-- workspace. Memberships are admin-write under RLS, so members (invitees)
-- need this narrow door; it can only touch the caller's own row and only the
-- two onboarding columns.
create or replace function public.save_onboarding_progress(
  _org_id uuid,
  _step text,
  _completed boolean default false,
  _done text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or public.is_anonymous_session() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if (_step is not null and _step !~ '^[a-z0-9][a-z0-9:_-]{0,63}$')
     or (_done is not null and _done !~ '^[a-z0-9][a-z0-9:_-]{0,63}$') then
    raise exception 'invalid_step' using errcode = 'P0001';
  end if;
  update public.memberships
  set onboarding_step = _step,
      onboarding_completed_at = case
        when _completed then coalesce(onboarding_completed_at, now())
        else onboarding_completed_at
      end,
      onboarding_done = case
        when _done is null or _done = any (onboarding_done) then onboarding_done
        else array_append(onboarding_done, _done)
      end
  where org_id = _org_id and user_id = (select auth.uid());
  if not found then
    raise exception 'not_a_member' using errcode = 'P0001';
  end if;
end;
$$;

-- Execute grants: authenticated only, never anon/public.
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.is_slug_available(text)',
    'public.create_workspace(text, text)',
    'public.accept_invitation(text)',
    'public.join_workspace_by_link(text)',
    'public.my_pending_invitations()',
    'public.save_onboarding_progress(uuid, text, boolean, text)'
  ] loop
    execute format('revoke execute on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ============================================================================
-- Policies
-- ============================================================================

-- Co-members can read each other's profiles (member lists, mentions).
drop policy if exists "profiles: co-members read" on public.profiles;
create policy "profiles: co-members read"
  on public.profiles for select to authenticated
  using (exists (
    select 1
    from public.memberships me
    join public.memberships them on them.org_id = me.org_id
    where me.user_id = (select auth.uid())
      and them.user_id = profiles.id
  ));

-- Anonymous (Turnstile) sessions never touch workspace tables.
do $$
declare
  t text;
begin
  foreach t in array array['organizations', 'memberships', 'invitations'] loop
    execute format('drop policy if exists %I on public.%I', t || ': no anon', t);
    execute format(
      'create policy %I on public.%I as restrictive for all to authenticated '
      'using (coalesce(((select auth.jwt()) ->> ''is_anonymous'')::boolean, false) = false) '
      'with check (coalesce(((select auth.jwt()) ->> ''is_anonymous'')::boolean, false) = false)',
      t || ': no anon', t
    );
  end loop;
end;
$$;

-- ============================================================================
-- Avatars: public-read bucket for profile photos (onboarding "Set up your
-- profile"). Teammates must see each other's photos, which the private,
-- owner-only `user-files` bucket can't serve. Writes are confined to the
-- owner's "<user_id>/" prefix, like user-files.
-- ============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'avatars',
  'avatars',
  true,
  2097152,
  array['image/png', 'image/jpeg', 'image/webp', 'image/gif']
)
on conflict (id) do nothing;

drop policy if exists "avatars: select own" on storage.objects;
create policy "avatars: select own"
  on storage.objects for select to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists "avatars: insert own" on storage.objects;
create policy "avatars: insert own"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
    and coalesce(((select auth.jwt()) ->> 'is_anonymous')::boolean, false) = false
  );

drop policy if exists "avatars: update own" on storage.objects;
create policy "avatars: update own"
  on storage.objects for update to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text)
  with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists "avatars: delete own" on storage.objects;
create policy "avatars: delete own"
  on storage.objects for delete to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- Workspace invitations (B2B PR 2) · docs/WORKSPACES.md, docs/ERD.md
--
-- Builds on 20261118000000_workspaces.sql:
--   * privacy: replaces the co-member profiles read policy (which exposed whole
--     profile rows, phone included) with workspace_members(), a safe-columns RPC;
--   * invitations: create/resend in SQL (tokens generated here, returned once,
--     stored only as SHA-256), accept by invitation id for the "You've been
--     invited" screen, and token previews for the public /invite + /join pages;
--   * invite links: reset / enable / restrict by domain (free-mail blocked);
--   * roles: only owners may grant, change or remove the owner role;
--   * account deletion: a sole owner of a workspace with other members can't be
--     deleted until ownership is transferred (DB-enforced; the delete-account
--     edge function pre-checks for a clear message).
--
-- Append-only + idempotent-friendly. Every function: security definer,
-- set search_path = '', stable snake_case error messages.

-- ============================================================================
-- Privacy: no more whole-row profile reads between co-members
-- ============================================================================

drop policy if exists "profiles: co-members read" on public.profiles;

-- ============================================================================
-- Helpers (internal — not executable by API roles)
-- ============================================================================

-- 32 random bytes, URL-safe base64 without padding (43 chars).
create or replace function public.new_url_token()
returns text
language sql
volatile
set search_path = ''
as $$
  select translate(rtrim(encode(extensions.gen_random_bytes(32), 'base64'), '='), '+/', '-_');
$$;

create or replace function public.sha256_hex(_value text)
returns text
language sql
immutable
set search_path = ''
as $$
  select encode(sha256(convert_to(_value, 'UTF8')), 'hex');
$$;

-- Free-mail domains can't restrict an invite link (anyone could join).
-- Mirrored in packages/app/src/workspaces.ts (FREE_MAIL_DOMAINS).
create or replace function public.is_free_mail_domain(_domain text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select lower(_domain) = any (array[
    'gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com',
    'msn.com', 'yahoo.com', 'ymail.com', 'icloud.com', 'me.com', 'mac.com',
    'aol.com', 'proton.me', 'protonmail.com', 'gmx.com', 'gmx.de', 'mail.com',
    'yandex.com', 'zoho.com', 'hey.com', 'fastmail.com'
  ]);
$$;

-- The caller is an owner of the workspace.
create or replace function public.is_org_owner(_org uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.memberships m
    where m.org_id = _org and m.user_id = (select auth.uid()) and m.role = 'owner'
  );
$$;

-- Shared acceptance: membership (idempotent), audit stamp, active workspace.
-- Callers have already checked status/expiry/email.
create or replace function public.apply_invitation(_inv public.invitations)
returns public.organizations
language plpgsql
security definer
set search_path = ''
as $$
declare
  _uid uuid := (select auth.uid());
  _org public.organizations;
begin
  insert into public.memberships (org_id, user_id, role)
  values (_inv.org_id, _uid, _inv.role)
  on conflict (org_id, user_id) do nothing;

  update public.invitations
  set status = 'accepted', accepted_at = now(), accepted_by = _uid
  where id = _inv.id;

  update public.profiles set last_org_id = _inv.org_id where id = _uid;

  select * into _org from public.organizations o where o.id = _inv.org_id;
  return _org;
end;
$$;

-- Validate a pending invite for the caller; raises the stable error codes.
create or replace function public.check_invitation_for_caller(_inv public.invitations)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  _email text;
begin
  if _inv.status = 'revoked' then
    raise exception 'invite_revoked' using errcode = 'P0001';
  end if;
  if _inv.status = 'accepted' then
    raise exception 'invite_used' using errcode = 'P0001';
  end if;
  if _inv.expires_at is not null and _inv.expires_at <= now() then
    raise exception 'invite_expired' using errcode = 'P0001';
  end if;
  _email := public.confirmed_email();
  if _email is null or _email <> lower(_inv.email) then
    raise exception 'invite_wrong_account' using errcode = 'P0001';
  end if;
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.new_url_token()',
    'public.apply_invitation(public.invitations)',
    'public.check_invitation_for_caller(public.invitations)'
  ] loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
  end loop;
end;
$$;

-- ============================================================================
-- Accepting
-- ============================================================================

-- accept_invitation: same contract as before, now sharing the helpers. An
-- already-accepted invite stays idempotent for the person who accepted it.
create or replace function public.accept_invitation(_token text)
returns public.organizations
language plpgsql
security definer
set search_path = ''
as $$
declare
  _uid uuid := (select auth.uid());
  _inv public.invitations;
  _org public.organizations;
begin
  if _uid is null or public.is_anonymous_session() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if _token is null or char_length(_token) < 16 then
    raise exception 'invite_not_found' using errcode = 'P0001';
  end if;

  select * into _inv from public.invitations i
  where i.token_hash = public.sha256_hex(_token)
  for update;
  if not found then
    raise exception 'invite_not_found' using errcode = 'P0001';
  end if;
  if _inv.status = 'accepted' and _inv.accepted_by = _uid then
    select * into _org from public.organizations o where o.id = _inv.org_id;
    return _org;
  end if;

  perform public.check_invitation_for_caller(_inv);
  return public.apply_invitation(_inv);
end;
$$;

-- accept_pending_invitation: the "You've been invited" screen — the invitee
-- holds no token, but their CONFIRMED email matching the invite is the proof.
create or replace function public.accept_pending_invitation(_invitation_id uuid)
returns public.organizations
language plpgsql
security definer
set search_path = ''
as $$
declare
  _uid uuid := (select auth.uid());
  _inv public.invitations;
begin
  if _uid is null or public.is_anonymous_session() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;

  select * into _inv from public.invitations i where i.id = _invitation_id for update;
  if not found then
    raise exception 'invite_not_found' using errcode = 'P0001';
  end if;

  perform public.check_invitation_for_caller(_inv);
  return public.apply_invitation(_inv);
end;
$$;

-- ============================================================================
-- Members list (safe columns only)
-- ============================================================================

create or replace function public.workspace_members(_org uuid)
returns table (
  user_id uuid,
  display_name text,
  avatar_url text,
  title text,
  email text,
  role text,
  joined_at timestamptz,
  is_you boolean
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_org_member(_org) then
    raise exception 'not_a_member' using errcode = 'P0001';
  end if;
  return query
    select
      m.user_id,
      p.display_name,
      p.avatar_url,
      p.title,
      u.email::text,
      m.role,
      m.created_at,
      m.user_id = (select auth.uid())
    from public.memberships m
    join public.profiles p on p.id = m.user_id
    left join auth.users u on u.id = m.user_id
    where m.org_id = _org
    order by
      case m.role when 'owner' then 0 when 'admin' then 1 else 2 end,
      m.created_at;
end;
$$;

-- ============================================================================
-- Creating / resending invitations
-- ============================================================================

-- create_invitations: owners/admins invite by email. Returns one row per
-- distinct address; `invite_token` (plaintext, shown once) is set for rows the
-- server should email. ~50 invites per workspace per day.
create or replace function public.create_invitations(
  _org uuid,
  _emails text[],
  _role text default 'member',
  _expires_days integer default 7
)
returns table (
  invite_email text,
  result text,
  invite_token text,
  invitation_id uuid
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  _uid uuid := (select auth.uid());
  _days integer := least(30, greatest(1, coalesce(_expires_days, 7)));
  _sent_today integer;
  _addr text;
  _token text;
  _id uuid;
begin
  if _uid is null or public.is_anonymous_session() or public.confirmed_email() is null then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if not public.is_org_admin(_org) then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if _role not in ('member', 'admin') then
    raise exception 'invalid_role' using errcode = 'P0001';
  end if;
  if coalesce(cardinality(_emails), 0) = 0 or cardinality(_emails) > 50 then
    raise exception 'invalid_email_list' using errcode = 'P0001';
  end if;

  select count(*) into _sent_today
  from public.invitations i
  where i.org_id = _org and i.created_at > now() - interval '1 day';

  for _addr in
    select distinct lower(btrim(e)) from unnest(_emails) as e where btrim(e) <> ''
  loop
    invite_email := _addr;
    invite_token := null;
    invitation_id := null;

    if _addr !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
      result := 'invalid';
    elsif exists (
      select 1 from public.memberships m
      join auth.users u on u.id = m.user_id
      where m.org_id = _org and lower(u.email) = _addr
    ) then
      result := 'already_member';
    elsif _sent_today >= 50 then
      result := 'rate_limited';
    else
      _token := public.new_url_token();
      -- Re-inviting a pending address rotates its token and expiry.
      update public.invitations i
      set token_hash = public.sha256_hex(_token),
          expires_at = now() + make_interval(days => _days),
          invited_by = _uid,
          role = _role
      where i.org_id = _org and lower(i.email) = _addr and i.status = 'pending'
      returning i.id into _id;
      if _id is null then
        insert into public.invitations (org_id, email, role, token_hash, invited_by, expires_at)
        values (_org, _addr, _role, public.sha256_hex(_token), _uid, now() + make_interval(days => _days))
        returning id into _id;
        _sent_today := _sent_today + 1;
      end if;
      result := 'invited';
      invite_token := _token;
      invitation_id := _id;
      _id := null;
    end if;
    return next;
  end loop;
end;
$$;

-- resend_invitation: rotate a pending invite's token + expiry (the old link
-- stops working) and return the new token for the server to email.
create or replace function public.resend_invitation(
  _invitation_id uuid,
  _expires_days integer default 7
)
returns table (invite_email text, invite_token text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  _inv public.invitations;
  _token text := public.new_url_token();
  _days integer := least(30, greatest(1, coalesce(_expires_days, 7)));
begin
  if (select auth.uid()) is null or public.is_anonymous_session() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  select * into _inv from public.invitations i where i.id = _invitation_id for update;
  if not found or not public.is_org_admin(_inv.org_id) then
    raise exception 'invite_not_found' using errcode = 'P0001';
  end if;
  if _inv.status <> 'pending' then
    raise exception 'invite_not_pending' using errcode = 'P0001';
  end if;
  update public.invitations
  set token_hash = public.sha256_hex(_token),
      expires_at = now() + make_interval(days => _days),
      invited_by = (select auth.uid())
  where id = _inv.id;
  invite_email := _inv.email;
  invite_token := _token;
  return next;
end;
$$;

-- ============================================================================
-- Public previews (the /invite/[token] and /join/[token] pages)
-- ============================================================================

-- invitation_preview: what the token holder may see. Never returns hashes.
create or replace function public.invitation_preview(_token text)
returns table (
  status text,
  org_name text,
  org_slug text,
  logo_url text,
  inviter_name text,
  email text,
  role text,
  expires_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  _inv public.invitations;
begin
  if _token is null or char_length(_token) < 16 then
    status := 'not_found';
    return next;
    return;
  end if;
  select * into _inv from public.invitations i
  where i.token_hash = public.sha256_hex(_token);
  if not found then
    status := 'not_found';
    return next;
    return;
  end if;

  status := case
    when _inv.status = 'revoked' then 'revoked'
    when _inv.status = 'accepted' then 'used'
    when _inv.expires_at is not null and _inv.expires_at <= now() then 'expired'
    else 'valid'
  end;
  select o.name, o.slug, o.logo_url into org_name, org_slug, logo_url
  from public.organizations o where o.id = _inv.org_id;
  select p.display_name into inviter_name
  from public.profiles p where p.id = _inv.invited_by;
  email := _inv.email;
  role := _inv.role;
  expires_at := _inv.expires_at;
  return next;
end;
$$;

-- join_link_preview: workspace name/logo for an invite link.
create or replace function public.join_link_preview(_token text)
returns table (
  status text,
  org_name text,
  org_slug text,
  logo_url text,
  allowed_domains text[]
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  _org public.organizations;
begin
  if _token is null or char_length(_token) < 16 then
    status := 'not_found';
    return next;
    return;
  end if;
  select * into _org from public.organizations o
  where o.join_token_hash = public.sha256_hex(_token);
  if not found then
    status := 'not_found';
    return next;
    return;
  end if;
  status := case when _org.join_link_enabled then 'valid' else 'disabled' end;
  org_name := _org.name;
  org_slug := _org.slug;
  logo_url := _org.logo_url;
  allowed_domains := _org.allowed_domains;
  return next;
end;
$$;

-- ============================================================================
-- Invite links (owners/admins)
-- ============================================================================

-- reset_join_link: new token (old link stops working), link enabled; the
-- plaintext is returned once.
create or replace function public.reset_join_link(_org uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  _token text := public.new_url_token();
begin
  if (select auth.uid()) is null or public.is_anonymous_session()
     or not public.is_org_admin(_org) then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  update public.organizations
  set join_token_hash = public.sha256_hex(_token), join_link_enabled = true
  where id = _org;
  return _token;
end;
$$;

-- set_join_link: enable/disable and restrict to company domains.
create or replace function public.set_join_link(
  _org uuid,
  _enabled boolean,
  _allowed_domains text[] default '{}'
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  _domains text[];
  _d text;
begin
  if (select auth.uid()) is null or public.is_anonymous_session()
     or not public.is_org_admin(_org) then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  select coalesce(array_agg(distinct lower(btrim(d))), '{}')
  into _domains
  from unnest(coalesce(_allowed_domains, '{}')) as d
  where btrim(d) <> '';
  foreach _d in array _domains loop
    if _d !~ '^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$' then
      raise exception 'invalid_domain' using errcode = 'P0001';
    end if;
    if public.is_free_mail_domain(_d) then
      raise exception 'free_mail_domain' using errcode = 'P0001';
    end if;
  end loop;
  update public.organizations
  set join_link_enabled = coalesce(_enabled, join_link_enabled),
      allowed_domains = _domains
  where id = _org;
end;
$$;

-- ============================================================================
-- Roles: only owners grant, change or remove the owner role
-- ============================================================================

create or replace function public.guard_owner_role()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  _uid uuid := (select auth.uid());
  _org uuid := coalesce(new.org_id, old.org_id);
begin
  -- Service role / internal jobs (no JWT) and cascades from a deleted
  -- workspace or profile are not user actions.
  if _uid is null then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' and (
    not exists (select 1 from public.organizations o where o.id = old.org_id)
    or not exists (select 1 from public.profiles p where p.id = old.user_id)
  ) then
    return old;
  end if;

  if tg_op = 'INSERT' then
    if new.role = 'owner'
       and not exists (
         select 1 from public.organizations o
         where o.id = new.org_id and o.owner_id = new.user_id
       )
       and not public.is_org_owner(new.org_id) then
      raise exception 'owners_only' using errcode = 'P0001';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if (old.role = 'owner' or new.role = 'owner')
       and old.role is distinct from new.role
       and not public.is_org_owner(_org) then
      raise exception 'owners_only' using errcode = 'P0001';
    end if;
    return new;
  end if;

  -- DELETE: removing another owner takes an owner (leaving yourself is fine,
  -- subject to the last-owner guard).
  if old.role = 'owner' and old.user_id <> _uid and not public.is_org_owner(_org) then
    raise exception 'owners_only' using errcode = 'P0001';
  end if;
  return old;
end;
$$;

drop trigger if exists memberships_guard_owner_role on public.memberships;
create trigger memberships_guard_owner_role
  before insert or update or delete on public.memberships
  for each row execute function public.guard_owner_role();

-- ============================================================================
-- Account deletion: sole owners of shared workspaces must transfer first
-- ============================================================================

-- Workspaces where _user is the only owner and someone else is a member.
create or replace function public.blocking_owned_workspaces(_user uuid)
returns table (org_id uuid, org_name text, member_count integer)
language sql
stable
security definer
set search_path = ''
as $$
  select o.id, o.name, (select count(*)::integer from public.memberships x where x.org_id = o.id)
  from public.organizations o
  join public.memberships me on me.org_id = o.id and me.user_id = _user and me.role = 'owner'
  where not exists (
      select 1 from public.memberships other
      where other.org_id = o.id and other.role = 'owner' and other.user_id <> _user
    )
    and exists (
      select 1 from public.memberships other
      where other.org_id = o.id and other.user_id <> _user
    );
$$;

-- The caller's own blocking workspaces (delete-account pre-check, settings UI).
create or replace function public.my_blocking_workspaces()
returns table (org_id uuid, org_name text, member_count integer)
language sql
stable
security definer
set search_path = ''
as $$
  select * from public.blocking_owned_workspaces((select auth.uid()));
$$;

create or replace function public.guard_profile_delete()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from public.blocking_owned_workspaces(old.id)) then
    raise exception 'sole_owner_with_members' using errcode = 'P0001',
      hint = 'Transfer ownership of shared workspaces before deleting the account.';
  end if;
  return old;
end;
$$;

drop trigger if exists profiles_guard_delete on public.profiles;
create trigger profiles_guard_delete
  before delete on public.profiles
  for each row execute function public.guard_profile_delete();

-- ============================================================================
-- Execute grants
-- ============================================================================

do $$
declare
  f text;
begin
  -- Signed-in users only.
  foreach f in array array[
    'public.accept_invitation(text)',
    'public.accept_pending_invitation(uuid)',
    'public.workspace_members(uuid)',
    'public.create_invitations(uuid, text[], text, integer)',
    'public.resend_invitation(uuid, integer)',
    'public.reset_join_link(uuid)',
    'public.set_join_link(uuid, boolean, text[])',
    'public.my_blocking_workspaces()',
    'public.is_org_owner(uuid)'
  ] loop
    execute format('revoke execute on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;

  -- Public pages (token holders may be signed out).
  foreach f in array array[
    'public.invitation_preview(text)',
    'public.join_link_preview(text)'
  ] loop
    execute format('revoke execute on function %s from public', f);
    execute format('grant execute on function %s to anon, authenticated', f);
  end loop;

  -- Server-side only.
  execute 'revoke execute on function public.blocking_owned_workspaces(uuid) from public, anon, authenticated';
end;
$$;

-- profiles.email + auth events.
--
-- 1. profiles.email — mirrored from auth.users (read-own), kept in sync on
--    email change and anonymous → permanent conversion (also fixes the stale
--    profiles.is_anonymous flag). Modules can't read auth.users, so this is
--    how they learn a user's email.
-- 2. auth_events — one row per auth email sent, sign-in and account change,
--    derived from Supabase's auth audit log by a trigger. Links and codes are
--    never stored. docs/AUTH.md → Auth events.
--
-- Append-only + idempotent-friendly. docs/ERD.md.

-- ============================================================================
-- 1. profiles.email
-- ============================================================================

alter table public.profiles add column if not exists email text;
create index if not exists profiles_email_lower_idx
  on public.profiles (lower(email));

comment on column public.profiles.email is
  'Mirror of auth.users.email (null for anonymous users). Read-own under RLS; written only by auth triggers.';

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name, avatar_url, is_anonymous, is_staff, email)
  values (
    new.id,
    coalesce(
      new.raw_user_meta_data ->> 'display_name',
      new.raw_user_meta_data ->> 'name',
      split_part(coalesce(new.email, ''), '@', 1)
    ),
    new.raw_user_meta_data ->> 'avatar_url',
    coalesce(new.is_anonymous, false),
    -- First NON-anonymous profile becomes staff (the founder/admin); anon never.
    (not coalesce(new.is_anonymous, false))
      and (select count(*) = 0 from public.profiles where is_anonymous = false),
    nullif(new.email, '')
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

-- Keep email + anonymity in step with auth.users (email change confirmed,
-- anonymous visitor converted to a permanent account).
create or replace function public.handle_user_updated()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.profiles
     set email = nullif(new.email, ''),
         is_anonymous = coalesce(new.is_anonymous, false)
   where id = new.id
     and (email is distinct from nullif(new.email, '')
          or is_anonymous is distinct from coalesce(new.is_anonymous, false));
  return new;
end;
$$;

drop trigger if exists on_auth_user_updated on auth.users;
create trigger on_auth_user_updated
  after update of email, is_anonymous on auth.users
  for each row execute function public.handle_user_updated();

-- Backfill existing profiles.
update public.profiles p
   set email = nullif(u.email, ''),
       is_anonymous = coalesce(u.is_anonymous, false)
  from auth.users u
 where u.id = p.id
   and (p.email is distinct from nullif(u.email, '')
        or p.is_anonymous is distinct from coalesce(u.is_anonymous, false));


-- ============================================================================
-- 2. auth_events
-- ============================================================================

create table if not exists public.auth_events (
  id uuid primary key default gen_random_uuid(),
  audit_id uuid unique,
  user_id uuid not null references public.profiles (id) on delete cascade,
  email text,
  action text not null,
  category text not null check (category in ('email', 'session', 'account')),
  email_kind text check (email_kind in (
    'confirmation', 'sign_in_or_recovery', 'invite', 'email_change', 'reauthentication'
  )),
  occurred_at timestamptz not null default now()
);
create index if not exists auth_events_user_idx
  on public.auth_events (user_id, occurred_at desc);

comment on table public.auth_events is
  'Auth emails sent, sign-ins and account changes per user, derived from the Supabase auth audit log. Never contains links, codes or tokens. Read-own; written only by trigger.';

alter table public.auth_events enable row level security;
drop policy if exists "auth_events: select own" on public.auth_events;
create policy "auth_events: select own"
  on public.auth_events for select to authenticated
  using (user_id = (select auth.uid()));

-- Map one audit-log row to an auth_events row. Never raises: auth must not
-- fail because of bookkeeping.
create or replace function public.handle_auth_audit_entry()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  act text := new.payload ->> 'action';
  actor uuid;
  target uuid;
  cat text;
  kind text;
  addr text;
begin
  begin
    actor := nullif(new.payload ->> 'actor_id', '')::uuid;
  exception when others then
    actor := null;
  end;

  begin
    case act
      when 'user_confirmation_requested' then
        cat := 'email'; kind := 'confirmation'; target := actor;
      when 'user_recovery_requested' then
        -- GoTrue logs magic-link / email-OTP sign-ins and password resets the
        -- same way; they can't be told apart here.
        cat := 'email'; kind := 'sign_in_or_recovery'; target := actor;
      when 'user_reauthenticate_requested' then
        cat := 'email'; kind := 'reauthentication'; target := actor;
      when 'user_invited' then
        cat := 'email'; kind := 'invite';
        target := nullif(new.payload -> 'traits' ->> 'user_id', '')::uuid;
      when 'user_modified' then
        -- An email change request has no action of its own; detect it from
        -- the user row GoTrue just updated.
        if exists (
          select 1 from auth.users u
           where u.id = actor
             and coalesce(u.email_change, '') <> ''
             and u.email_change_sent_at > now() - interval '1 minute'
        ) then
          cat := 'email'; kind := 'email_change'; target := actor;
        else
          return new;
        end if;
      when 'login' then
        cat := 'session'; target := actor;
      when 'user_signedup', 'user_updated_password', 'user_deleted' then
        cat := 'account'; target := actor;
      else
        return new;
    end case;

    if target is null then
      return new;
    end if;
    -- Skip anonymous users and users without a profile (deleted, or not yet mirrored).
    if not exists (
      select 1 from public.profiles p where p.id = target and not p.is_anonymous
    ) then
      return new;
    end if;

    if kind = 'email_change' then
      select u.email_change into addr from auth.users u where u.id = target;
    else
      select u.email into addr from auth.users u where u.id = target;
    end if;

    insert into public.auth_events (audit_id, user_id, email, action, category, email_kind, occurred_at)
    values (new.id, target, nullif(addr, ''), act, cat, kind, coalesce(new.created_at, now()))
    on conflict (audit_id) do nothing;
  exception when others then
    raise warning 'auth_events: skipped audit entry % (%): %', new.id, act, sqlerrm;
  end;
  return new;
end;
$$;

-- Hosted projects may not let the migration role attach triggers to the auth
-- schema's audit table. Don't fail the migration if so; docs/AUTH.md explains
-- how to check that auth events are flowing.
do $$
begin
  execute 'drop trigger if exists on_auth_audit_entry on auth.audit_log_entries';
  execute 'create trigger on_auth_audit_entry
             after insert on auth.audit_log_entries
             for each row execute function public.handle_auth_audit_entry()';
exception when insufficient_privilege then
  raise notice 'auth_events: no privilege to attach a trigger to auth.audit_log_entries; auth events are disabled.';
end;
$$;

-- AI Chat · index shapes that match the queries.
--
-- * Threads are listed per user, newest first; messages are read per thread
--   in time order. Single-column (user_id) / (thread_id) indexes made Postgres
--   sort every list; the composite indexes return rows already ordered.
-- * Foreign keys that ON DELETE actions follow get an index, so deleting a
--   message or a profile doesn't scan the child table.
-- * The (channel) index had too few distinct values to help any query.
--
-- Reattach-friendly (if not exists / if exists).

create index if not exists mod_chat_threads_user_created_idx
  on public.mod_chat_threads (user_id, created_at desc);
drop index if exists public.mod_chat_threads_user_id_idx;

create index if not exists mod_chat_messages_thread_created_idx
  on public.mod_chat_messages (thread_id, created_at);
drop index if exists public.mod_chat_messages_thread_id_idx;

-- Channel conversations are looked up by (channel, contact_key).
create index if not exists mod_chat_threads_channel_contact_idx
  on public.mod_chat_threads (channel, contact_key)
  where contact_key is not null;
drop index if exists public.mod_chat_threads_channel_idx;

-- FK columns followed by ON DELETE CASCADE / SET NULL.
create index if not exists mod_chat_votes_message_idx
  on public.mod_chat_votes (message_id);
create index if not exists mod_chat_suggestions_user_idx
  on public.mod_chat_suggestions (user_id);
create index if not exists mod_chat_channel_contacts_user_idx
  on public.mod_chat_channel_contacts (user_id)
  where user_id is not null;

-- Dedupe rows are only ever deleted by age.
create index if not exists mod_chat_processed_inbound_received_idx
  on public.mod_chat_processed_inbound (received_at);

-- One scheduler (Supabase Cron) · policy-driven retention · append-only audit.
-- docs/ERD.md, docs/MODULES.md → Housekeeping, CLAUDE.md → Vendor features.
--
-- 1. Retention policies (private.retention_policies). Every purge reads its
--    window from here — no literal intervals in purge code — and honours a
--    legal hold. A later compliance module raises the minimums.
-- 2. Audit log (audit.events). Append-only: no role (service_role included)
--    may UPDATE or DELETE it; the only deletion path is the retention purge.
--    No foreign keys, so entries survive user deletion. Server code writes
--    through public.audit_log_event() (service role only).
-- 3. auth_events keeps history after an account is deleted (FK dropped).
-- 4. Housekeeping registry: modules register their purge functions;
--    private.run_housekeeping() runs core + module purges, each isolated, and
--    records the counts in the audit log.
-- 5. Supabase Cron (pg_cron, every plan) schedules:
--      * hourly housekeeping (in-database, no HTTP);
--      * every minute, the app's scheduled endpoints via pg_net, using the
--        app URL + cron secret the runtime bootstrap stores in Vault. Without
--        both secrets the calls are skipped (fresh clone, preview, CI).
--    This replaces Vercel Cron (Hobby: once a day, no retries).
--
-- Append-only + idempotent-friendly.

create extension if not exists pg_cron with schema pg_catalog;
grant usage on schema cron to postgres;
create extension if not exists pg_net with schema extensions;

create schema if not exists private;
revoke all on schema private from public;

-- ============================================================================
-- 1. Retention policies
-- ============================================================================

create table if not exists private.retention_policies (
  data_class text primary key check (data_class ~ '^[a-z][a-z0-9_]*$'),
  keep_days integer not null check (keep_days > 0),
  legal_hold boolean not null default false,
  description text,
  updated_at timestamptz not null default now()
);

comment on table private.retention_policies is
  'How long each class of data is kept. Purges read their window here; legal_hold suspends a class''s purge.';

-- Defaults sized for the Supabase Free plan. Re-running never overwrites a
-- value someone changed (on conflict do nothing).
insert into private.retention_policies (data_class, keep_days, description) values
  ('audit', 400, 'audit.events'),
  ('pii_activity', 365, 'Per-user activity history (auth_events, …)'),
  ('anonymous_users', 30, 'Anonymous users with no saved favorites, by last sign-in'),
  ('oauth_codes', 1, 'Expired or used MCP authorization codes'),
  ('oauth_tokens', 30, 'Revoked or expired MCP refresh tokens'),
  ('cron_history', 7, 'cron.job_run_details and pg_net responses')
on conflict (data_class) do nothing;

-- Cutoff timestamp for a class, or null when the class is unknown or on legal
-- hold (null = purge nothing — the safe default).
create or replace function private.retention_cutoff(_class text)
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $$
  select now() - make_interval(days => r.keep_days)
  from private.retention_policies r
  where r.data_class = _class and not r.legal_hold;
$$;

-- Modules declare their classes from their migrations (keeps existing values).
create or replace function public.kit_register_retention(
  _class text,
  _keep_days integer,
  _description text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce((select auth.role()), '') in ('authenticated', 'anon') then
    raise exception 'kit_register_retention: not allowed' using errcode = '42501';
  end if;
  insert into private.retention_policies (data_class, keep_days, description)
  values (_class, _keep_days, _description)
  on conflict (data_class) do nothing;
end;
$$;

-- ============================================================================
-- 2. Audit log
-- ============================================================================

create schema if not exists audit;
revoke all on schema audit from public, anon, authenticated, service_role;

comment on schema audit is
  'Append-only audit log. Not exposed through the Data API; written via public.audit_log_event().';

create table if not exists audit.events (
  id bigint generated always as identity primary key,
  occurred_at timestamptz not null default now(),
  actor_id uuid,          -- no FK: entries outlive the account
  actor_type text not null default 'system'
    check (actor_type in ('user', 'staff', 'system', 'service')),
  action text not null check (action ~ '^[a-z][a-z0-9_.:-]*$'),
  entity_type text,
  entity_id text,
  org_id uuid,            -- no FK: entries outlive the workspace
  meta jsonb not null default '{}'::jsonb check (jsonb_typeof(meta) = 'object')
);

alter table audit.events enable row level security;
revoke all on audit.events from public, anon, authenticated, service_role;

create index if not exists audit_events_occurred_brin
  on audit.events using brin (occurred_at);
create index if not exists audit_events_actor_idx
  on audit.events (actor_id, occurred_at desc)
  where actor_id is not null;
create index if not exists audit_events_entity_idx
  on audit.events (entity_type, entity_id);

-- The only write path. IDs and labels belong here; content and PII don't.
create or replace function private.audit_emit(
  _action text,
  _actor_id uuid default null,
  _actor_type text default 'system',
  _entity_type text default null,
  _entity_id text default null,
  _org_id uuid default null,
  _meta jsonb default '{}'::jsonb
)
returns bigint
language sql
security definer
set search_path = ''
as $$
  insert into audit.events (action, actor_id, actor_type, entity_type, entity_id, org_id, meta)
  values (_action, _actor_id, coalesce(_actor_type, 'system'), _entity_type, _entity_id, _org_id,
          coalesce(_meta, '{}'::jsonb))
  returning id;
$$;

-- Server code (service-role client) logs through this RPC.
create or replace function public.audit_log_event(
  _action text,
  _actor_id uuid default null,
  _actor_type text default 'service',
  _entity_type text default null,
  _entity_id text default null,
  _org_id uuid default null,
  _meta jsonb default '{}'::jsonb
)
returns bigint
language sql
security definer
set search_path = ''
as $$
  select private.audit_emit(_action, _actor_id, _actor_type, _entity_type, _entity_id, _org_id, _meta);
$$;

revoke execute on function public.audit_log_event(text, uuid, text, text, text, uuid, jsonb)
  from public, anon, authenticated;
grant execute on function public.audit_log_event(text, uuid, text, text, text, uuid, jsonb)
  to service_role;

-- ============================================================================
-- 3. auth_events survives account deletion
-- ============================================================================

-- user_id stays (read-own RLS still matches it); history becomes pseudonymous
-- once the account is gone and is removed by the pii_activity policy instead.
alter table public.auth_events drop constraint if exists auth_events_user_id_fkey;

-- ============================================================================
-- 4. Housekeeping
-- ============================================================================

create table if not exists private.housekeeping_tasks (
  fn text primary key check (fn ~ '^[a-z_][a-z0-9_]*\.[a-z_][a-z0-9_]*$'),
  module text not null,
  created_at timestamptz not null default now()
);

comment on table private.housekeeping_tasks is
  'Purge functions (schema.name, no arguments, returns integer rows removed) run hourly by private.run_housekeeping().';

-- Modules register / unregister from their migrations and drop.sql.
create or replace function public.kit_register_housekeeping(_fn text, _module text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce((select auth.role()), '') in ('authenticated', 'anon') then
    raise exception 'kit_register_housekeeping: not allowed' using errcode = '42501';
  end if;
  insert into private.housekeeping_tasks (fn, module) values (_fn, _module)
  on conflict (fn) do update set module = excluded.module;
end;
$$;

create or replace function public.kit_unregister_housekeeping(_module text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce((select auth.role()), '') in ('authenticated', 'anon') then
    raise exception 'kit_unregister_housekeeping: not allowed' using errcode = '42501';
  end if;
  delete from private.housekeeping_tasks where module = _module;
end;
$$;

-- Core purges. Bounded batches; the hourly schedule drains any backlog.
create or replace function private.kit_housekeeping()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  _cutoff timestamptz;
  _n integer;
  _total integer := 0;
begin
  -- auth_events (pii_activity)
  _cutoff := private.retention_cutoff('pii_activity');
  if _cutoff is not null then
    delete from public.auth_events e
    where e.id in (
      select x.id from public.auth_events x where x.occurred_at < _cutoff limit 10000
    );
    get diagnostics _n = row_count; _total := _total + _n;
  end if;

  -- MCP authorization codes: expired or consumed
  _cutoff := private.retention_cutoff('oauth_codes');
  if _cutoff is not null then
    delete from public.mcp_authorization_codes c
    where c.expires_at < _cutoff or c.consumed_at < _cutoff;
    get diagnostics _n = row_count; _total := _total + _n;
  end if;

  -- MCP refresh tokens: revoked or expired
  _cutoff := private.retention_cutoff('oauth_tokens');
  if _cutoff is not null then
    delete from public.mcp_refresh_tokens t
    where coalesce(t.revoked_at, t.expires_at) < _cutoff;
    get diagnostics _n = row_count; _total := _total + _n;
  end if;

  -- Anonymous users with nothing saved (Supabase's documented cleanup).
  -- Deleting the auth user cascades to everything they own.
  _cutoff := private.retention_cutoff('anonymous_users');
  if _cutoff is not null then
    delete from auth.users u
    where u.id in (
      select a.id
      from auth.users a
      where a.is_anonymous
        and coalesce(a.last_sign_in_at, a.created_at) < _cutoff
        and not exists (select 1 from public.content_favorites f where f.user_id = a.id)
      limit 1000
    );
    get diagnostics _n = row_count; _total := _total + _n;
  end if;

  -- Scheduler history (Supabase doesn't prune it).
  _cutoff := private.retention_cutoff('cron_history');
  if _cutoff is not null then
    delete from cron.job_run_details d where d.end_time < _cutoff;
    get diagnostics _n = row_count; _total := _total + _n;
  end if;

  -- The audit log itself, only by its own (long) policy.
  _cutoff := private.retention_cutoff('audit');
  if _cutoff is not null then
    delete from audit.events a
    where a.id in (select x.id from audit.events x where x.occurred_at < _cutoff limit 10000);
    get diagnostics _n = row_count; _total := _total + _n;
  end if;

  return _total;
end;
$$;

-- Runs the core purge and every registered module purge. One failing task is
-- logged and skipped; it never blocks the others. Each run leaves one audit
-- entry with the per-task counts.
create or replace function private.run_housekeeping()
returns jsonb
language plpgsql
security definer
set search_path = ''
set statement_timeout = '5min'
as $$
declare
  _report jsonb := '{}'::jsonb;
  _task record;
  _n integer;
begin
  begin
    _n := private.kit_housekeeping();
    _report := _report || jsonb_build_object('kit', _n);
  exception when others then
    _report := _report || jsonb_build_object('kit', 'error: ' || sqlerrm);
  end;

  for _task in select h.fn, h.module from private.housekeeping_tasks h order by h.fn loop
    begin
      if to_regprocedure(_task.fn || '()') is null then
        _report := _report || jsonb_build_object(_task.fn, 'missing');
        continue;
      end if;
      execute format('select %s()', _task.fn) into _n;
      _report := _report || jsonb_build_object(_task.fn, coalesce(_n, 0));
    exception when others then
      _report := _report || jsonb_build_object(_task.fn, 'error: ' || sqlerrm);
    end;
  end loop;

  perform private.audit_emit('housekeeping.run', null, 'system', null, null, null, _report);
  return _report;
end;
$$;

-- ============================================================================
-- 5. Scheduler: Supabase Cron → app endpoints
-- ============================================================================

-- Written by the runtime bootstrap (lib/db/bootstrap.ts) on every boot: the
-- app's origin as seen FROM the database, and the cron bearer secret. Only
-- rewritten when a value changed. Postgres-only (not exposed, not granted).
create or replace function private.sync_scheduler_secrets(_app_url text, _cron_secret text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  _name text;
  _value text;
  _id uuid;
  _current text;
begin
  foreach _name in array array['kit_app_url', 'kit_cron_secret'] loop
    _value := case _name when 'kit_app_url' then _app_url else _cron_secret end;
    select s.id, s.decrypted_secret into _id, _current
    from vault.decrypted_secrets s where s.name = _name;
    if _value is null or _value = '' then
      if _id is not null then
        delete from vault.secrets where id = _id;
      end if;
    elsif _id is null then
      perform vault.create_secret(_value, _name, 'Set by the dream-starter-kit runtime bootstrap');
    elsif _current is distinct from _value then
      perform vault.update_secret(_id, _value);
    end if;
  end loop;
end;
$$;

revoke all on function private.sync_scheduler_secrets(text, text) from public;

-- Fire-and-forget GET to an app path with the cron bearer secret. Returns the
-- pg_net request id, or null when the app URL / secret aren't configured.
create or replace function private.call_app(_path text, _timeout_ms integer default 55000)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  _url text;
  _secret text;
begin
  select decrypted_secret into _url from vault.decrypted_secrets where name = 'kit_app_url';
  select decrypted_secret into _secret from vault.decrypted_secrets where name = 'kit_cron_secret';
  if _url is null or _secret is null then
    return null;
  end if;
  return net.http_get(
    url := rtrim(_url, '/') || _path,
    headers := jsonb_build_object('Authorization', 'Bearer ' || _secret),
    timeout_milliseconds := _timeout_ms
  );
end;
$$;

revoke all on function private.call_app(text, integer) from public;

-- Idempotent: cron.schedule upserts by job name.
select cron.schedule(
  'kit-housekeeping',
  '17 * * * *',
  $$select private.run_housekeeping()$$
);

-- Payload Jobs Queue: enqueue due scheduled tasks, then run a bounded batch.
select cron.schedule(
  'kit-payload-jobs',
  '* * * * *',
  $$select private.call_app('/cms-api/payload-jobs/handle-schedules');
    select private.call_app('/cms-api/payload-jobs/run?limit=10')$$
);

-- Staff notification broadcasts (moves into the Jobs Queue in a later step).
select cron.schedule(
  'kit-notifications-dispatch',
  '* * * * *',
  $$select private.call_app('/api/cms/notifications/dispatch')$$
);

-- Daily site-license report (was a Vercel Cron).
select cron.schedule(
  'kit-dream-site-report',
  '23 5 * * *',
  $$select private.call_app('/api/cms/dream-site/report')$$
);

-- Scheduler, step 2: Payload's Jobs Queue owns the app's background work.
--
-- * One tick per minute: `/cms-api/payload-jobs/run?allQueues=true` first
--   queues every due scheduled task (notifications dispatch, site report,
--   scheduled publishing), then runs a bounded batch. The separate
--   handle-schedules call and the two per-route schedules are retired.
-- * Modules that serve their own cron route register it here with
--   kit_register_app_schedule() (and remove it in drop.sql with
--   kit_unregister_app_schedule()). Paths are limited to /api/mod/… and the
--   call carries the cron bearer secret.
--
-- Append-only + idempotent-friendly.

select cron.schedule(
  'kit-payload-jobs',
  '* * * * *',
  $$select private.call_app('/cms-api/payload-jobs/run?allQueues=true&limit=10')$$
);

do $$
begin
  if exists (select 1 from cron.job where jobname = 'kit-notifications-dispatch') then
    perform cron.unschedule('kit-notifications-dispatch');
  end if;
  if exists (select 1 from cron.job where jobname = 'kit-dream-site-report') then
    perform cron.unschedule('kit-dream-site-report');
  end if;
end;
$$;

create or replace function public.kit_register_app_schedule(
  _name text,
  _cron text,
  _path text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce((select auth.role()), '') in ('authenticated', 'anon') then
    raise exception 'kit_register_app_schedule: not allowed' using errcode = '42501';
  end if;
  if _name !~ '^mod-[a-z0-9-]+$' then
    raise exception 'kit_register_app_schedule: name must look like mod-<slug>-<job>'
      using errcode = '22023';
  end if;
  if _path !~ '^/api/mod/[a-z0-9-]+/[A-Za-z0-9/_?=&.-]*$' then
    raise exception 'kit_register_app_schedule: path must be a module route (/api/mod/<slug>/…)'
      using errcode = '22023';
  end if;
  perform cron.schedule(_name, _cron, format('select private.call_app(%L)', _path));
end;
$$;

create or replace function public.kit_unregister_app_schedule(_name text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce((select auth.role()), '') in ('authenticated', 'anon') then
    raise exception 'kit_unregister_app_schedule: not allowed' using errcode = '42501';
  end if;
  if exists (select 1 from cron.job where jobname = _name) then
    perform cron.unschedule(_name);
  end if;
end;
$$;

revoke execute on function public.kit_register_app_schedule(text, text, text) from public, anon, authenticated;
revoke execute on function public.kit_unregister_app_schedule(text) from public, anon, authenticated;

-- cms.users mirror: a durable queue instead of a mirror call on every render.
--
-- `cms.users` must list every permanent user (docs: CLAUDE.md → CMS auth).
-- The mirror used to run from five request paths plus a backstop in the app
-- shell layout (one Payload query per authenticated page render), and a missed
-- call was only repaired by running `pnpm cms:backfill-users` by hand.
--
-- Now a trigger on public.profiles enqueues the user id on Supabase Queues
-- (pgmq, available on every plan) whenever a permanent profile is created or
-- a mirrored field changes. The `cms-user-sync` Payload task drains the queue
-- every minute. pgmq is at-least-once (a message read but not acknowledged
-- reappears after its visibility timeout), so the drain is idempotent.
-- Messages carry the user id only — never PII.
--
-- The queue isn't exposed through the Data API; server code reads it through
-- two service-role-only RPCs.
--
-- Append-only + idempotent-friendly.

create extension if not exists pgmq;

do $$
begin
  if not exists (select 1 from pgmq.list_queues() q where q.queue_name = 'cms_user_sync') then
    perform pgmq.create('cms_user_sync');
  end if;
end;
$$;

create or replace function private.enqueue_cms_user_sync()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.is_anonymous then
    return new;
  end if;
  -- Never block the profile write over bookkeeping.
  begin
    perform pgmq.send('cms_user_sync', jsonb_build_object('user_id', new.id));
  exception when others then
    raise warning 'cms_user_sync: enqueue failed for %: %', new.id, sqlerrm;
  end;
  return new;
end;
$$;

drop trigger if exists profiles_enqueue_cms_sync on public.profiles;
create trigger profiles_enqueue_cms_sync
  after insert or update of email, display_name, avatar_url, phone, title, is_staff, is_anonymous
  on public.profiles
  for each row execute function private.enqueue_cms_user_sync();

-- Read up to _n messages, hidden from other readers for _vt seconds.
create or replace function public.cms_user_sync_read(_n integer default 100, _vt integer default 120)
returns table (msg_id bigint, user_id uuid, read_ct integer)
language sql
security definer
set search_path = ''
as $$
  select m.msg_id, (m.message ->> 'user_id')::uuid, m.read_ct
  from pgmq.read('cms_user_sync', greatest(coalesce(_vt, 120), 10), least(greatest(coalesce(_n, 100), 1), 500)) m;
$$;

-- Acknowledge processed messages (delete, not archive: nothing to keep).
create or replace function public.cms_user_sync_ack(_msg_ids bigint[])
returns integer
language sql
security definer
set search_path = ''
as $$
  select count(*)::integer from pgmq.delete('cms_user_sync', _msg_ids);
$$;

-- Enqueue every permanent user (the `pnpm cms:backfill-users` catch-up).
create or replace function public.cms_user_sync_enqueue_all()
returns integer
language sql
security definer
set search_path = ''
as $$
  select count(*)::integer
  from public.profiles p,
       lateral pgmq.send('cms_user_sync', jsonb_build_object('user_id', p.id))
  where not p.is_anonymous;
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.cms_user_sync_read(integer, integer)',
    'public.cms_user_sync_ack(bigint[])',
    'public.cms_user_sync_enqueue_all()'
  ] loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end;
$$;

-- Billing 1.1 · one Stripe webhook, safe under retries and reordering.
--
-- The Stripe webhook moved from a Supabase edge function into the module's
-- public route (POST /api/mod/billing/stripe/webhook). This adds what makes a
-- webhook correct at scale:
--   * mod_billing_webhook_events — Stripe event ids already handled, so a
--     redelivered event is acknowledged without being applied twice;
--   * stripe_event_at on subscriptions + mod_billing_apply_subscription():
--     an OLDER event arriving after a newer one no longer rolls the
--     subscription back (Stripe doesn't guarantee delivery order);
--   * mod_billing_user_id_by_email(): an indexed lookup on profiles.email
--     instead of paging through every auth user per checkout;
--   * a retention purge for the event ledger (kit housekeeping).
-- Every function refuses signed-in and anonymous callers (module SQL can't
-- GRANT/REVOKE, so each checks its caller).
--
-- Reattach-friendly (if not exists / or replace).

create table if not exists public.mod_billing_webhook_events (
  id text primary key, -- Stripe event id (evt_…)
  type text not null,
  received_at timestamptz not null default now()
);
create index if not exists mod_billing_webhook_events_received_idx
  on public.mod_billing_webhook_events using brin (received_at);

-- Server-only ledger: RLS on, no policies (service role bypasses RLS).
alter table public.mod_billing_webhook_events enable row level security;

alter table public.mod_billing_subscriptions
  add column if not exists stripe_event_at timestamptz,
  add column if not exists updated_at timestamptz not null default now();

-- Upsert one subscription row unless the stored row came from a NEWER event.
create or replace function public.mod_billing_apply_subscription(
  _row jsonb,
  _event_at timestamptz
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  _applied boolean;
begin
  if coalesce((select auth.role()), '') in ('authenticated', 'anon') then
    raise exception 'mod_billing_apply_subscription: not allowed' using errcode = '42501';
  end if;
  -- The subscription may arrive before its price (Stripe doesn't order
  -- events, and prices created before the webhook existed never arrive): keep
  -- a stub so the foreign key holds; the price.* event fills it in.
  if _row ->> 'price_id' is not null then
    insert into public.mod_billing_prices (id, active)
    values (_row ->> 'price_id', true)
    on conflict (id) do nothing;
  end if;
  insert into public.mod_billing_subscriptions as s (
    id, user_id, price_id, status, quantity, cancel_at_period_end,
    current_period_end, stripe_event_at, updated_at
  )
  values (
    _row ->> 'id',
    (_row ->> 'user_id')::uuid,
    _row ->> 'price_id',
    _row ->> 'status',
    (_row ->> 'quantity')::integer,
    coalesce((_row ->> 'cancel_at_period_end')::boolean, false),
    (_row ->> 'current_period_end')::timestamptz,
    _event_at,
    now()
  )
  on conflict (id) do update
    set user_id = excluded.user_id,
        price_id = excluded.price_id,
        status = excluded.status,
        quantity = excluded.quantity,
        cancel_at_period_end = excluded.cancel_at_period_end,
        current_period_end = excluded.current_period_end,
        stripe_event_at = excluded.stripe_event_at,
        updated_at = now()
    where s.stripe_event_at is null
       or excluded.stripe_event_at is null
       or excluded.stripe_event_at >= s.stripe_event_at
  returning true into _applied;
  return coalesce(_applied, false);
end;
$$;

create or replace function public.mod_billing_user_id_by_email(_email text)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if coalesce((select auth.role()), '') in ('authenticated', 'anon') then
    raise exception 'mod_billing_user_id_by_email: not allowed' using errcode = '42501';
  end if;
  -- Served by profiles_email_lower_idx.
  return (
    select p.id from public.profiles p
    where lower(p.email) = lower(btrim(_email))
    order by p.created_at
    limit 1
  );
end;
$$;

